import json,hashlib
P=Path('docs/planning');O=P/'campaign3-history-betrayal-rev1';B=P/'campaign3-history-universe-rev1'
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def ref(p):return dict(path=Path(p).as_posix(),sha256=hashlib.sha256(Path(p).read_bytes()).hexdigest())
def walk(v,p=''):
 if isinstance(v,dict):
  for k,x in v.items():yield from walk(x,p+'/'+k)
 elif isinstance(v,list):
  for i,x in enumerate(v):yield from walk(x,p+'/'+str(i))
 elif isinstance(v,str):yield p,v
specs={'docs/formal/BETRAYAL_PUBLIC_CONTRACT.md': 'Accepted betrayal-public0.1: prior admitted own promise strictly before first outcome, nonfulfillment, linked intent/control and current willingness separate. Three-valued conjunction any false→0, else missing→unknown, alltrue→1. Controlled reports not generated commitment/target-action pipeline. First outcome fixed, correction successor required. OutcomeOnly/CurrentPersonBeliefOnly/NoLearning/TruthOracle retained. Prospective information/cooperation, no forgiveness/repair.', 'docs/planning/BETRAYAL_READINESS.md': 'Prospective failure versus intentional violation distinction, no raw betrayal flag. Requires prior expectation, fallible intent/control, false correction, independent willingness and later privacy. Actual target lifecycle/intent/execution guarantees cannot be imported from earlier profiles merely by citation. Accepted consumer prospective.', 'docs/planning/CAMPAIGN3_BETRAYAL_QUALIFICATION.md': 'VER-C3-BETRAYAL-001:6 models32 runs288 prefixes256 advancing32 terminal;24primary+3outcome rollback=27 new/328 reference/build historical. Same failed commitment with corrected intent/control removes appraisal; late/simultaneous/missing promise not prior. Explicit no-promise/success knownzero. Willingness changes cooperation separately; correction information7/9→1/2 not positive repair bonus. False explanation at fixed truth allowed. No general moral law.', 'docs/planning/BETRAYAL_IMPLEMENTATION_FINDINGS.md': 'Initial24 tests pass; first build TS2345 mutable-array helper incompatible readonly canonical items. Only parameter annotation corrected, runtime/model unchanged. Observer admission chronology not verified real promise timing; first outcome fixed. Same histories across serious competitors, whole later privacy. General source trust, recognition, uncertainty, blame and enacted response remain open.', 'docs/planning/BETRAYAL_PUBLIC_PLAN_REV1.json': 'Prospective32 original runs/six models with exact source/test/contract and ExperimentIdentity/ComparisonCase bindings. Controlled incident tokens and independently gated claims, no hidden truth as lawful appraisal input. Final corrected production bytes bound.', 'docs/planning/BETRAYAL_PUBLIC_RESULT_REV1.json': 'Complete32-row288-prefix aggregate from four disjoint workers. Fresh decoded original assertions verify temporal promise admission, independent intent/control/willingness, unknown/zero, immutable history and later privacy.256 advance32 terminal historical, not fresh runtime replay.', 'docs/planning/BETRAYAL_CLOSURE_REV1.json': 'Original closure freshly authenticates source/model/allocation/plan/result/workers, preservation,24+3 tests/328 reference/finalbuild. Records1264..1277 namespace1181;1277/0 historical. Supplement adds validation not models/runs/production. Integrity not fresh288 restores or faults.', 'docs/planning/BETRAYAL_PRESERVATION_REV1.json': 'Eleven exact artifacts preserve first build failure, passing primary tests, findings/model freeze and seven original source files. Source diff only readonly helper annotation; no rejected public cohort or psychological candidate falsification.', 'docs/planning/BETRAYAL_TESTS_REV1.json': 'Historical24 primary PASS covers13 stages+commit during explanation update, comparisons/privacy/ownership/malformed ingress/save. Passing behavioral tests did not imply TypeScript build success; actual first-outcome history writes supplemented separately.', 'docs/planning/BETRAYAL_OUTCOME_ROLLBACK_TESTS_REV1.json': 'Three historical PASS supplement at history-a/history-b/commit on first outcome after promise acquisition. Source verifies control history actually changes and fault boundary reached before asserting exact state/output/trace/queue/allocator/RNG rollback and failed-save rejection. Distinct real-write coverage, not new public runs.', 'docs/planning/BETRAYAL_REFERENCE_TESTS_REV1.json': 'Historical328 reference assertions PASS. Titles/paths/timings backing to reviewed mechanisms, not new betrayal findings or fresh suite execution.', 'docs/planning/BETRAYAL_BUILD_REV1.json': 'Historical first FAIL TS2345 readonly-array typing mismatch, despite24 behavioral tests passing. Exact source preserved; construction typing issue not changed psychological law.', 'docs/planning/BETRAYAL_BUILD_REV2.json': 'Historical corrected build PASS after readonly annotation, preceding final supplement-bound build. Not new behavior or fresh validation.', 'docs/planning/BETRAYAL_BUILD_REV3.json': 'Historical final build PASS with exact source and supplemental test artifacts bound; not fresh build or full active-suite claim.', 'docs/planning/betrayal-public-workers-rev1/0.json': 'Worker partition0: modulo4 roster, original identities, output/two observer-view hashes and aggregate. Fresh32 stored-view original contrasts, not288-prefix replay. Preserve missing versus false promise/intent/control and whole later privacy, not labels alone.', 'docs/planning/betrayal-public-workers-rev1/1.json': 'Worker partition1: modulo4 roster, original identities, output/two observer-view hashes and aggregate. Fresh32 stored-view original contrasts, not288-prefix replay. Preserve missing versus false promise/intent/control and whole later privacy, not labels alone.', 'docs/planning/betrayal-public-workers-rev1/2.json': 'Worker partition2: modulo4 roster, original identities, output/two observer-view hashes and aggregate. Fresh32 stored-view original contrasts, not288-prefix replay. Preserve missing versus false promise/intent/control and whole later privacy, not labels alone.', 'docs/planning/betrayal-public-workers-rev1/3.json': 'Worker partition3: modulo4 roster, original identities, output/two observer-view hashes and aggregate. Fresh32 stored-view original contrasts, not288-prefix replay. Preserve missing versus false promise/intent/control and whole later privacy, not labels alone.'}
